import assert from "node:assert/strict";
import { mkdtempSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test, { after, before } from "node:test";
import { startRmnProvider } from "./rmn-provider.mjs";
import { run as runReferral, ACTOR as FINANCE, CONTRACT as REFERRAL_CONTRACT, CATALOG_DIGEST } from "../../../../finance-and-market-services-section/src/contract-economic-service-referrals.mjs";
import { run as runAssay } from "../../../../finance-and-market-services-section/src/contract-witness-bit-assay.mjs";
import { digest, makeCommodityLot, makeCommodityUtterance, makeWitnessBitProduction } from "../../../../finance-and-market-services-section/src/witness-bit.mjs";
import { deriveDeterministicServiceExtent, executeTokenClaimResolution, planTokenClaimResolution, proposeResolutionEffect, resolutionEffectCell } from "../src/token-claim-resolution.mjs";
import { createLissResidueActuator } from "../src/liss-residue-actuator.mjs";
import { CHILD_OPERATION_TYPE, demandCommitment } from "../src/typed-rmn-inference-procurement.mjs";
import { formWorkClassAmortizationLot } from "../src/work-class-amortization.mjs";
import { ACTOR as CRYPTOGRAPHY, CONTRACT as CRYPTOGRAPHY_CONTRACT, run as runCryptography } from "../../../../../../../../561-group/services/red-cup-engineering/services/cryptographic-services-section/src/cryptographic-services.mjs";

const AT = "2026-07-19T17:30:00.000Z";
const CUSTOMER = "urn:ame:test-customer";
const WORK_LOT = "urn:ame:inference-work-lot-service";
const CUSTOMER_CAIP10 = "eip155:31337:0x1111111111111111111111111111111111111111";
const PROVIDER_CAIP10 = "eip155:31337:0x2222222222222222222222222222222222222222";

function production(utterance, actor, evidence) {
  return makeWitnessBitProduction({ utterance, tokenArticulated: true, claimArticulated: false, illocution: { actor, force: "requests", authority: "urn:contract:test-token-claim-resolution", at: AT, evidence: [digest(evidence)] } });
}

function candidateLot() {
  const utterance = makeCommodityUtterance({ token: { id: "urn:test:account-7" }, claim: { predicate: "has-balance", value: "3.000 HIVE" } });
  return makeCommodityLot({ producer: CUSTOMER, utterances: [utterance], productions: [production(utterance, CUSTOMER, "observed-account-record")] });
}

function serviceClaimLot(financeData) {
  const question = { "@context": "https://www.w3.org/ns/activitystreams", id: "urn:test:referral-question", type: "Question", actor: WORK_LOT, target: FINANCE, object: { type: "EconomicServiceReferralQuery", contract: REFERRAL_CONTRACT, intent: "assay-witness-bit-commodity", catalogDigest: CATALOG_DIGEST } };
  const answer = runReferral(question, "query-service-referrals", AT, { FINANCE_MARKET_DATA_ROOT: financeData });
  assert.equal(answer.type, "Answer");
  return answer.object.serviceClaimLot;
}

function request(intent = "assay-witness-bit-commodity") {
  const candidate = candidateLot();
  const context = { candidate };
  const utterance = makeCommodityUtterance({ token: { id: candidate.id }, claim: { type: "ServiceResolutionClaim", intent, contextDigest: digest(context) } });
  const workLot = makeCommodityLot({ producer: CUSTOMER, utterances: [utterance], productions: [production(utterance, CUSTOMER, context)] });
  return { workLot, context, serviceClaimLots: [] };
}

function advertisedServiceLot(actor, contract, intent = "assay-witness-bit-commodity") {
  const utterance = makeCommodityUtterance({ token: { id: actor, contract }, claim: { type: "ServiceCapabilityClaim", intent, executionClass: "deterministic-service", boundaryKind: "test-provider", operations: { solicit: "solicit-service", invoke: "invoke-service" }, inputKind: "CommodityUtteranceLot", outputKind: "CommodityUtteranceAssay", carrierEvidenceDigest: digest({ actor, contract }), availability: "unknown", targetAcceptanceRequired: true } });
  return makeCommodityLot({ producer: actor, utterances: [utterance], productions: [production(utterance, actor, { actor, contract })] });
}

function financeMarket(financeData) {
  let solicitations = 0, invocations = 0;
  return {
    counts: () => ({ solicitations, invocations }),
    solicit(candidate, value) {
      solicitations += 1;
      const activity = { "@context": "https://www.w3.org/ns/activitystreams", id: `urn:test:assay-solicitation:${solicitations}`, type: "Offer", actor: WORK_LOT, target: candidate.token.id, object: { type: "ServiceSolicitation", contract: candidate.token.contract, candidate: value.context.candidate } };
      return runAssay(activity, candidate.claim.operations.solicit, AT, { FINANCE_MARKET_DATA_ROOT: financeData });
    },
    invoke(candidate, offer) {
      invocations += 1;
      const cap = { type: "Capability", holder: candidate.token.id, invocationTarget: candidate.token.id, parentOffer: offer.id, attenuation: { candidateDigest: offer.object.candidateDigest, assayProfile: offer.object.assayProfile.id }, capTP: { target: candidate.token.id, method: candidate.claim.operations.invoke }, allowedActions: [candidate.claim.operations.invoke, "provider-local-write"] };
      const activity = { "@context": "https://www.w3.org/ns/activitystreams", id: `urn:test:assay-invocation:${invocations}`, type: "Accept", actor: WORK_LOT, target: candidate.token.id, object: { type: "ServiceContract", contract: candidate.token.contract, offer, capability: cap } };
      return runAssay(activity, candidate.claim.operations.invoke, AT, { FINANCE_MARKET_DATA_ROOT: financeData });
    }
  };
}

async function effectFor(plan) {
  return proposeResolutionEffect(plan, {
    caller: { actor: CUSTOMER, caip10: CUSTOMER_CAIP10 },
    provider: { actor: plan.selected.candidate.token.id, caip10: PROVIDER_CAIP10 },
    parent: null
  }, AT);
}

test("FCA derives the witnessed deterministic service extent from token/claim lots", () => {
  const financeData = mkdtempSync(join(tmpdir(), "finance-claim-referral-"));
  const value = request(); value.serviceClaimLots = [serviceClaimLot(financeData)];
  const extent = deriveDeterministicServiceExtent(value);
  assert.equal(extent.derivation.disposition, "deterministic-candidates-derived");
  assert.deepEqual(extent.derivation.candidate_extent, [value.serviceClaimLots[0].id]);
  assert.deepEqual(extent.requiredAttributes, ["intent:assay-witness-bit-commodity", "execution-class:deterministic-service"]);
  assert.equal(extent.derivation.galois_connection_witnessed, true);
  assert.equal(extent.frontierInferenceCalls, 0);
});

test("a real Finance assay work class resolves through one typed RMN cover and an independent customer assay with no model call", async () => {
  const financeData = mkdtempSync(join(tmpdir(), "finance-claim-circuit-"));
  const value = request(); value.serviceClaimLots = [serviceClaimLot(financeData)];
  const market = financeMarket(financeData);
  let actuatorCalls = 0;
  const plan = await planTokenClaimResolution(value, { market, actuator: { solicit() { actuatorCalls += 1; } } });
  assert.equal(plan.disposition, "deterministic-service-selected");
  assert.throws(() => resolutionEffectCell(plan, { caller: { actor: "urn:ame:foreign-caller", caip10: CUSTOMER_CAIP10 }, provider: { actor: FINANCE, caip10: PROVIDER_CAIP10 } }), /caller-must-be-work-lot-producer/);
  assert.throws(() => resolutionEffectCell(plan, { caller: { actor: CUSTOMER, caip10: CUSTOMER_CAIP10 }, provider: { actor: "urn:ame:foreign-provider", caip10: PROVIDER_CAIP10 } }), /provider-must-be-selected-service-token/);
  const effect = await effectFor(plan);
  const result = await executeTokenClaimResolution(plan, value, { market, effect, now: AT });
  assert.equal(result.disposition, "deterministically-resolved-and-customer-assayed");
  assert.equal(result.customerAccepted, true);
  assert.equal(result.frontierInferenceCalls, 0);
  assert.equal(actuatorCalls, 0);
  assert.deepEqual(market.counts(), { solicitations: 1, invocations: 1 });
  assert.deepEqual(result.effect.outcome, { positiveEvidence: true, negativeEvidence: false });
  assert.match(result.effect.witness, /^ni:\/\/\/sha-256;/u);
});

test("the repeated work class re-derives the same script route and still spends zero frontier inference", async () => {
  const financeData = mkdtempSync(join(tmpdir(), "finance-claim-repeat-"));
  const value = request(); value.serviceClaimLots = [serviceClaimLot(financeData)];
  const market = financeMarket(financeData);
  const firstPlan = await planTokenClaimResolution(value, { market });
  const secondPlan = await planTokenClaimResolution(value, { market });
  assert.equal(firstPlan.selected.candidate.lot.id, secondPlan.selected.candidate.lot.id);
  assert.equal(firstPlan.frontierInferenceCalls + secondPlan.frontierInferenceCalls, 0);
});

test("customer witness assigns measured frontier and Leader-labor decline to the repeatedly settled work-class token", async () => {
  const correctionClaimIds = ["handle-the-data-the-firm-generates-through-its-movements", "offload-work-to-free-cloud-endpoints-and-scripts"];
  for (const correctionId of correctionClaimIds) {
    const correctionRecord = JSON.parse(readFileSync(new URL(`../../../../../data/records/ideas/ideas/${correctionId}.json`, import.meta.url), "utf8"));
    assert.equal(correctionRecord.id, correctionId);
  }
  const financeData = mkdtempSync(join(tmpdir(), "finance-amortization-"));
  const value = request(); value.serviceClaimLots = [serviceClaimLot(financeData)];
  const market = financeMarket(financeData);
  const firstPlan = await planTokenClaimResolution(value, { market });
  const repeatPlan = await planTokenClaimResolution(value, { market });
  const first = await executeTokenClaimResolution(firstPlan, value, { market, effect: await effectFor(firstPlan), now: AT });
  const repeat = await executeTokenClaimResolution(repeatPlan, value, { market, effect: await effectFor(repeatPlan), now: AT });
  const postconditionCommitment = digest("customer-assayed-conformant-commodity-lot");
  const formed = formWorkClassAmortizationLot({
    workClassToken: "urn:work-class:assay-witness-bit-commodity",
    producer: CUSTOMER,
    authority: "urn:contract:test-work-class-amortization",
    at: AT,
    baseline: { id: "urn:observation:model-first-incumbent", postconditionCommitment, customerAccepted: false, frontierInferenceCalls: 1, leaderCorrectionClaimIds: correctionClaimIds },
    repetitions: [
      { id: first.effect.witness, postconditionCommitment, customerAccepted: first.customerAccepted, frontierInferenceCalls: first.frontierInferenceCalls, leaderCorrectionClaimIds: [] },
      { id: repeat.effect.witness, postconditionCommitment, customerAccepted: repeat.customerAccepted, frontierInferenceCalls: repeat.frontierInferenceCalls, leaderCorrectionClaimIds: [] },
    ],
  });
  assert.equal(formed.assay.status, "conformant");
  assert.equal(formed.claim.amortized, true);
  assert.deepEqual(formed.metrics.frontierInferenceCalls, { baseline: 1, repeated: [0, 0], declined: true });
  assert.deepEqual(formed.metrics.leaderCorrections, { baseline: 2, repeated: [0, 0], declined: true });
  assert.equal(formed.lot.trace.initial.utterance.token.id, "urn:work-class:assay-witness-bit-commodity");
});

test("comparable deterministic extents settle on the cheapest live service offer without an inference call", async () => {
  const value = request();
  value.serviceClaimLots = [advertisedServiceLot("urn:ame:unaccounted-script", "assay-service"), advertisedServiceLot("urn:ame:expensive-script", "assay-service"), advertisedServiceLot("urn:ame:cheap-script", "assay-service")];
  const market = { solicit(candidate) {
    const amount = candidate.token.id === "urn:ame:unaccounted-script" ? 0 : candidate.token.id === "urn:ame:cheap-script" ? 1 : 3;
    return { "@context": "https://www.w3.org/ns/activitystreams", id: `urn:offer:${amount}`, type: "Offer", actor: candidate.token.id, target: WORK_LOT, object: { type: "ExecutableServiceOffer", contract: candidate.token.contract, consideration: { amount, unit: "assay-operation" } } };
  } };
  const plan = await planTokenClaimResolution(value, { market });
  assert.equal(plan.disposition, "deterministic-service-selected");
  assert.equal(plan.selected.candidate.token.id, "urn:ame:cheap-script");
  assert.deepEqual(plan.comparison.ranked.map(({ offer }) => offer.object.consideration.amount), [1, 3]);
  assert.equal(plan.frontierInferenceCalls, 0);
});

test("a non-Finance cryptographic work class closes through the same FCA route and a customer-owned published-vector assay", async () => {
  const expectedDigest = "0x1c8aff950685c2ed4bc3174f3472287b56d9517b9c948127319a09a7a36deac8";
  const context = { operation: "keccak256", message: "hello", expectedDigest };
  const workUtterance = makeCommodityUtterance({ token: { id: "urn:test:keccak-hello" }, claim: { type: "ServiceResolutionClaim", intent: "derive-keccak256", contextDigest: digest(context) } });
  const workLot = makeCommodityLot({ producer: CUSTOMER, utterances: [workUtterance], productions: [production(workUtterance, CUSTOMER, context)] });
  const serviceLot = advertisedServiceLot(CRYPTOGRAPHY, CRYPTOGRAPHY_CONTRACT, "derive-keccak256");
  const value = { workLot, context, serviceClaimLots: [serviceLot] };
  let solicitations = 0, invocations = 0;
  const market = {
    solicit(candidate) {
      solicitations += 1;
      return runCryptography({ "@context": "https://www.w3.org/ns/activitystreams", id: `urn:test:crypto-solicitation:${solicitations}`, type: "Offer", actor: WORK_LOT, target: candidate.token.id, object: { type: "ServiceSolicitation", contract: candidate.token.contract, operation: context.operation } }, candidate.claim.operations.solicit);
    },
    invoke(candidate, offer) {
      invocations += 1;
      return runCryptography({
        "@context": "https://www.w3.org/ns/activitystreams",
        id: `urn:test:crypto-invocation:${invocations}`,
        type: "Accept",
        actor: WORK_LOT,
        target: candidate.token.id,
        object: {
          type: "ServiceContract",
          contract: candidate.token.contract,
          offer,
          capability: { type: "Capability", holder: candidate.token.id, invocationTarget: candidate.token.id, parentOffer: offer.id, capTP: { target: candidate.token.id, method: candidate.claim.operations.invoke }, allowedActions: [candidate.claim.operations.invoke] },
          request: { operation: context.operation, message: context.message },
        },
      }, candidate.claim.operations.invoke);
    },
  };
  const plan = await planTokenClaimResolution(value, { market });
  assert.equal(plan.disposition, "deterministic-service-selected");
  const effect = await effectFor(plan);
  const customerAssayer = ({ providerResult, request: customerRequest }) => {
    const observedDigest = providerResult?.object?.result?.digest ?? null;
    const assay = { type: "PublishedVectorCryptographicAssay", vector: "ethereum-keccak256-hello", expectedDigest: customerRequest.context.expectedDigest, observedDigest };
    return { type: "CustomerResultAssay", assay, accepted: providerResult?.type === "Accept" && observedDigest === customerRequest.context.expectedDigest, basis: "customer-owned-published-vector-comparison" };
  };
  const result = await executeTokenClaimResolution(plan, value, { market, customerAssayer, effect, now: AT });
  assert.equal(result.disposition, "deterministically-resolved-and-customer-assayed");
  assert.equal(result.customerAssay.basis, "customer-owned-published-vector-comparison");
  assert.equal(result.customerAssay.assay.observedDigest, expectedDigest);
  assert.equal(result.frontierInferenceCalls, 0);
  assert.deepEqual({ solicitations, invocations }, { solicitations: 1, invocations: 1 });
});

test("customer-assayer liveness loss halts without silently accepting provider output", async () => {
  const financeData = mkdtempSync(join(tmpdir(), "finance-assayer-liveness-"));
  const value = request(); value.serviceClaimLots = [serviceClaimLot(financeData)];
  const market = financeMarket(financeData);
  const plan = await planTokenClaimResolution(value, { market });
  const effect = await effectFor(plan);
  await assert.rejects(
    executeTokenClaimResolution(plan, value, { market, customerAssayer() { throw new Error("customer-assayer-offline"); }, effect, now: AT }),
    /customer-result-assay-unavailable:customer-assayer-offline/,
  );
});

test("only a no-cover residue is admitted to an inference actuator", async () => {
  const value = request("novel-opaque-inquiry");
  const provider = "urn:ame:test-inference-provider", card = "http://127.0.0.1:17771/.well-known/agent-card.json";
  value.actuatorTerms = { workType: "classification", requiredCapabilities: ["classification", "json-output"], difficulty: 0.3, maxTokens: 256, outputContract: { format: "json", schema: { type: "object" } }, mode: "dry-run", agentCards: [{ actor: provider, url: card }] };
  let solicited = 0, invoked = 0, submittedDemand, submittedContract;
  const supplier = { actor: provider, exchange(activity) { solicited += 1; submittedDemand = activity.object; return { "@context": activity["@context"], id: "urn:test:typed-offer", type: "Offer", actor: provider, target: activity.actor, inReplyTo: activity.id, object: { type: "TypedRmnInferenceServiceOffer", contract: "ni:///sha-256;AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA", providerAccount: PROVIDER_CAIP10, agentCard: card, operationType: CHILD_OPERATION_TYPE, model: "test-model", mode: "dry-run", workTypes: ["classification"], capabilities: ["classification", "json-output"], maximumDifficulty: 1, maximumOutputTokens: 1024, consideration: { amount: 1, unit: "test-actuation", monetaryClaim: false }, requestCommitment: demandCommitment(activity.object), availability: "accepted-task-must-still-settle", customerAcceptanceRequired: true } }; } };
  const actuator = createLissResidueActuator({ suppliers: [supplier], caller: { actor: CUSTOMER, account: CUSTOMER_CAIP10 }, liss: { invoke(message) { invoked += 1; submittedContract = message; return { protocol: "A2A", protocolVersion: "1.0", completion: "ni:///sha-256;BBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB", disposition: "completion", candidate: "{}" }; } }, now: () => AT });
  const plan = await planTokenClaimResolution(value, { actuator });
  assert.equal(plan.disposition, "actuator-required");
  assert.equal(plan.residue.admissibleNextServiceClass, "inference-actuator");
  assert.equal(plan.frontierInferenceCalls, 0);
  const result = await executeTokenClaimResolution(plan, value, { actuator });
  assert.equal(result.disposition, "actuator-candidate-pending-customer-assay");
  assert.equal(result.frontierInferenceCalls, 1);
  assert.deepEqual({ solicited, invoked }, { solicited: 1, invoked: 1 });
  assert.equal(submittedDemand.input.includes(value.workLot.id), true);
  assert.equal(submittedDemand.input.includes(plan.residue.type), true);
  assert.equal(submittedContract.role, "ROLE_USER");
  assert.equal(submittedContract.parts.length, 1);
  assert.equal(submittedContract.parts[0].mediaType, "application/rmn+cbor");
  assert.equal(result.result.status, "candidate-not-yet-customer-assayed");
});

test("the deterministic traversal is admitted by the hired RMN provider as exactly one positive cover", async () => {
  const financeData = mkdtempSync(join(tmpdir(), "finance-claim-evm-"));
  const value = request(); value.serviceClaimLots = [serviceClaimLot(financeData)];
  const market = financeMarket(financeData);
  const plan = await planTokenClaimResolution(value, { market });
  const proposal = await effectFor(plan);
  const result = await executeTokenClaimResolution(plan, value, { market, effect: proposal, now: AT });
  assert.equal(result.disposition, "deterministically-resolved-and-customer-assayed");
  assert.equal(result.frontierInferenceCalls, 0);
  assert.equal(result.effect.proposal, proposal.semanticId);
  assert.deepEqual(result.effect.outcome, { positiveEvidence: true, negativeEvidence: false });
});
