const NODE_ID = "finance-and-market-services-section";

export function financeRecords(root, contract, type) {
  return readSettlementRecords(root, `${contract}.${type}`);
}

function semanticIdentity(value) {
  return semanticId(relationalRwilDocument(value));
}

function recordIdentity(type, value) {
  if (type === "eavt") return `eavt:${semanticIdentity([value?.e ?? null, value?.a ?? null, value?.t ?? null])}`;
  return typeof value?.id === "string" ? `id:${value.id}` : `rmn:${semanticIdentity(value)}`;
}

export async function appendFinanceRecord({ root, contract, actor, type, value, recordedAt, env }) {
  const identity = recordIdentity(type, value);
  for (const prior of financeRecords(root, contract, type)) {
    if (recordIdentity(type, prior) !== identity) continue;
    return semanticIdentity(prior) === semanticIdentity(value)
      ? { status: "replayed", value: prior }
      : { status: "collision", value: prior };
  }
  const agentUrl = env?.RWIL_RDF_AGENT;
  if (!agentUrl) throw new Error("RWIL_RDF_AGENT must name the contracted RWIL/RDF provider");
  await recordSettlementRecord({
    agentUrl,
    root,
    nodeId: NODE_ID,
    settlement: FINANCE_SETTLEMENT,
    actor,
    category: `${contract}.${type}`,
    recordedAt,
    record: value,
  });
  return { status: "appended", value };
}

